import{_ as a,C as n,o as i,c as r,E as o,a2 as s}from"./chunks/framework.Cm6XCzck.js";const f=JSON.parse('{"title":"TMPA Core Specification — Release Candidate S0.6","description":"","frontmatter":{"title":"TMPA Core Specification — Release Candidate S0.6","outline":"deep","citation":{"work":"TMPA Core Specification","identifier":"TMPA-CORE-S0.6","language":"en","metadata":"/releases/tmpa/v1.0-rc1/metadata/core-specification.en.cff"}},"headers":[],"relativePath":"en/publications/tmpa-core-specification-s0.6/part-01.md","filePath":"en/publications/tmpa-core-specification-s0.6/part-01.md","lastUpdated":1786355271000}'),c={name:"en/publications/tmpa-core-specification-s0.6/part-01.md"};function d(l,e,p,u,h,m){const t=n("ArticleCover");return i(),r("div",null,[o(t,{image:"/assets/covers/tmpa-spec.svg",kicker:"Normative Specification",title:"TMPA Core Specification",summary:"Normative object, lifecycle, authority, three-valued judgment and deterministic reconstruction requirements.",version:"S0.6",status:"Release Candidate",languageHref:"/zh/publications/tmpa-core-specification-s0.6",languageLabel:"简体中文"}),e[0]||(e[0]=s(`<h1 id="tmpa-core-specification" tabindex="-1">TMPA Core Specification <a class="header-anchor" href="#tmpa-core-specification" aria-label="Permalink to &quot;TMPA Core Specification&quot;">​</a></h1><h2 id="textual-multi-agent-process-architecture-—-core-objects-reader-semantics-and-conformance" tabindex="-1">Textual Multi-Agent Process Architecture — Core Objects, Reader Semantics, and Conformance <a class="header-anchor" href="#textual-multi-agent-process-architecture-—-core-objects-reader-semantics-and-conformance" aria-label="Permalink to &quot;Textual Multi-Agent Process Architecture — Core Objects, Reader Semantics, and Conformance&quot;">​</a></h2><blockquote><p><strong>Specification Version:</strong> Release Candidate S0.6<br><strong>Historical Extraction Baseline:</strong> TMPA Draft V1.0-R24; current specification maintained directly in this GitHub document<br><strong>Status:</strong> Public Release Candidate<br><strong>Extraction Date:</strong> 2026-07-31<br><strong>Editorial Revision Date:</strong> 2026-08-09<br><strong>Authority:</strong> This GitHub document is the sole normative source for TMPA Core S0.6. The Architecture Paper is theoretical and the Implementation Case Report is evidentiary; neither may redefine this specification.</p></blockquote><hr><h1 id="_1-status-scope-and-conformance-boundary" tabindex="-1">1. Status, Scope, and Conformance Boundary <a class="header-anchor" href="#_1-status-scope-and-conformance-boundary" aria-label="Permalink to &quot;1. Status, Scope, and Conformance Boundary&quot;">​</a></h1><p>This document defines the vendor-neutral TMPA Core. It fixes the canonical governance object model, single-writer and lifecycle semantics, source aggregation, deterministic governance reconstruction, three-valued judgment algebra, reader output contract, trust assumptions, normative requirements, and C01–C14 conformance behavior.</p><p>TMPA Core governs process-responsibility evidence. It does not prescribe a model runtime, scheduler, storage engine, message transport, database, filesystem layout, identity provider, key-management system, or enterprise control plane. A profile may bind those mechanisms, but it MUST preserve the Core semantics and MUST identify every additional assumption or guarantee.</p><p>This release candidate separates three kinds of text:</p><ul><li><strong>normative requirements:</strong> Sections 9 and 10, using the terms defined in Section 9.1;</li><li><strong>architectural and algorithmic definitions required to interpret the normative clauses:</strong> Sections 2–8;</li><li><strong>informative extraction and traceability notes:</strong> Section 11 and Appendix A.</li></ul><p>The following are outside TMPA Core unless a named profile adds them: authenticated enterprise identity, credential issuance, recursive delegation, runtime admission control, protected or tamper-resistant storage, distributed consensus, semantic truth verification, Byzantine resilience, legal certification, and jurisdiction-specific compliance.</p><p>A conforming implementation MAY use files, database rows, object-store objects, or events as source artifacts. It MUST NOT claim conformance merely because it stores Markdown, produces logs, or implements a workflow state machine. Conformance is behavioral and depends on the observable object, lifecycle, reconstruction, conflict, recovery, and test requirements in Sections 9 and 10.</p><p>The publication contract is fixed across the three maintained documents: the <a href="/joinwell52/en/publications/tmpa-architecture-paper-a0.9">Architecture Paper A0.9</a> explains the theory, this Core Specification defines normative behavior, and the <a href="/joinwell52/en/publications/implementation-case-i0.8">Implementation Case Report I0.8</a> reports bounded engineering evidence. Their current guidance relation and historical co-evolution are distinct:</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>CURRENT GUIDANCE AND IMPLEMENTATION</span></span>
<span class="line"><span>TMPA theory and architecture</span></span>
<span class="line"><span>        ↓ formalized as normative behavior by</span></span>
<span class="line"><span>TMPA Core Specification</span></span>
<span class="line"><span>        ↓ projected through the file-based profile</span></span>
<span class="line"><span>FCoP protocol</span></span>
<span class="line"><span>        ↓ used by</span></span>
<span class="line"><span>CodeFlowMu engineering system</span></span>
<span class="line"><span></span></span>
<span class="line"><span>HISTORICAL CO-EVOLUTION</span></span>
<span class="line"><span>XiaoDian AI practice → early TMPA → FCoP extraction and maturation</span></span>
<span class="line"><span>                    → CodeFlowMu engineering implementation</span></span>
<span class="line"><span>FCoP + CodeFlowMu feedback → current TMPA formalization</span></span></code></pre></div><p>TMPA theory guides CodeFlowMu engineering, this Core fixes the normative behavior under evaluation, and FCoP provides the coordination protocol used by CodeFlowMu. The <code>fcop</code> and <code>fcop-mcp</code> Python packages are reference implementations of the protocol, not FCoP itself. Engineering feedback may motivate a later TMPA revision, but neither the FCoP protocol, its reference implementation, nor CodeFlowMu defines or exhausts TMPA Core.</p><hr><h1 id="_2-terminology-and-representation-stages" tabindex="-1">2. Terminology and Representation Stages <a class="header-anchor" href="#_2-terminology-and-representation-stages" aria-label="Permalink to &quot;2. Terminology and Representation Stages&quot;">​</a></h1><p>The paper fixes the following vocabulary so that semantic objects, physical storage, message behavior, and reconstructed views are not treated as interchangeable concepts.</p><table tabindex="0"><thead><tr><th>Canonical English term</th><th>Fixed Chinese equivalent</th><th>Fixed meaning</th><th>Not equivalent to</th></tr></thead><tbody><tr><td><strong>governed work item</strong></td><td><strong>受治理工作项</strong></td><td>the task, request, decision, or process subject whose responsibility and lifecycle are being governed</td><td>one file, one session, or one runtime job</td></tr><tr><td><strong>primary carrier</strong></td><td><strong>主载体</strong></td><td>the stable governance object that anchors the identifier and minimum governing context of one work item</td><td>a mutable record that every participant edits</td></tr><tr><td><strong>governance object</strong></td><td><strong>治理对象</strong></td><td>one canonical semantic unit authored by one creator under one responsible role and one writer stream</td><td>its storage path, transport envelope, or derived view</td></tr><tr><td><strong>textual message</strong></td><td><strong>文本消息</strong></td><td>the communication function of a governance object when it transfers work, evidence, review, or decision semantics</td><td>a separate object class or an ephemeral queue message</td></tr><tr><td><strong>state carrier</strong></td><td><strong>状态载体</strong></td><td>the persistence function through which an object, transition record, or profile-defined location contributes declared or current state evidence</td><td>shared mutable application state</td></tr><tr><td><strong>source artifact</strong></td><td><strong>来源工件</strong></td><td>one physical representation or observation of evidence, such as a file, database row, object-store item, or received event</td><td>the semantic governance object after validation</td></tr><tr><td><strong>source candidate</strong></td><td><strong>来源候选</strong></td><td>one discovered source artifact presented to the aggregation stage, including malformed or conflicting observations</td><td>an accepted authoritative object</td></tr><tr><td><strong>canonical candidate set</strong></td><td><strong>规范候选集合</strong></td><td>the source-preserving, parsed, indexed, and deterministically normalized collection returned by aggregation</td><td>the final governance conclusion</td></tr><tr><td><strong>writer stream</strong></td><td><strong>写者流</strong></td><td>the locally ordered sequence of governance objects published by one attributable writer</td><td>a global event log or total timeline</td></tr><tr><td><strong>source aggregator</strong></td><td><strong>来源聚合器</strong></td><td>the stage that discovers, preserves, parses, indexes, and normalizes source candidates without deciding governance truth</td><td>the governance reader</td></tr><tr><td><strong>governance reader</strong></td><td><strong>治理 Reader</strong></td><td>the deterministic stage that applies a fixed profile to the canonical candidate set</td><td>the storage layer, orchestrator, or model runtime</td></tr><tr><td><strong>governance graph and issue set</strong></td><td><strong>治理图与问题集合</strong></td><td>the reconstructed partial-order process view and the canonical unresolved-condition output</td><td>the original source evidence or an imposed total order</td></tr><tr><td><strong>lifecycle state</strong></td><td><strong>生命周期状态</strong></td><td>the current profile stage reconstructed from valid transitions or state observations</td><td>business acceptance, semantic truth, or proof that intended value was delivered</td></tr><tr><td><strong>business acceptance</strong></td><td><strong>业务验收</strong></td><td>an independent conclusion by an authorized role over a delivery claim and its supporting evidence</td><td>executor self-report, terminal storage location, or a <code>done</code> label</td></tr><tr><td><strong>completion claim</strong></td><td><strong>完成声明</strong></td><td>an inspectable assertion that a work item, deliverable, or child-work set satisfies its requirements</td><td>a self-authenticating completion fact</td></tr><tr><td><strong>work derivation</strong></td><td><strong>工作派生关系</strong></td><td>an explicit parent-child relation retaining scope, responsibility, and closure requirements</td><td>a transient runtime fork or an unproven task list</td></tr><tr><td><strong>governance decision</strong></td><td><strong>治理裁决</strong></td><td>an independent review, approval, rejection, change request, abstention, or human-escalation object</td><td>the lifecycle <code>review</code> stage itself</td></tr><tr><td><strong>inspection finding</strong></td><td><strong>巡检发现</strong></td><td>a reproducible drift or risk signal emitted by a reader, auditor, or governance-alert component</td><td>an automatically executed repair or business decision</td></tr></tbody></table><p>The three semantic judgments are also fixed across all documents: <code>valid</code> (<strong>有效</strong>) means the applicable evidence and rules establish acceptance; <code>invalid</code> (<strong>无效</strong>) means the rules establish rejection or violation; <code>undetermined</code> (<strong>未确定</strong>) means evidence is incomplete, conflicting, or awaiting an authorized resolution. View labels such as authoritative, quarantined, partial, disputed, and pending_human explain the presentation reason; they are not additional semantic values.</p><p>A single canonical governance object may be realized by different physical profiles. In FCoP, its source artifact is ordinarily a file plus path and event evidence; another profile may use a row, object, or event. Conversely, two source artifacts that declare the same object identifier but contain different canonical content are not two harmless copies: they are conflicting candidates that must be retained and evaluated under the profile. Throughout the architecture and normative chapters, <strong>object</strong> refers to the semantic unit, <strong>artifact</strong> to a physical or published engineering representation, and <strong>view</strong> to a reader-derived result.</p><hr><h1 id="_3-core-architecture-model" tabindex="-1">3. Core Architecture Model <a class="header-anchor" href="#_3-core-architecture-model" aria-label="Permalink to &quot;3. Core Architecture Model&quot;">​</a></h1><p>TMPA defines governance semantics, not a runtime component. Its architecture specifies which governance facts must be represented, how responsibility and lifecycle are expressed, and how independent evidence is reconstructed into an authoritative view. Storage, transport, scheduling, and model behavior remain implementation concerns unless a TMPA profile explicitly binds them.</p><h2 id="_3-1-governance-object" tabindex="-1">3.1 Governance Object <a class="header-anchor" href="#_3-1-governance-object" aria-label="Permalink to &quot;3.1 Governance Object&quot;">​</a></h2><p>A <strong>governance object</strong> is the smallest independently attributable semantic unit in TMPA. It may represent a task, report, review, approval, issue, lifecycle transition, role assignment, recovery action, or another document type published by a protocol profile. The object is distinct from its physical <strong>source artifact</strong>: FCoP may encode it as a file and path observation, while another profile may use a database row, object-store item, or event.</p><p>The terms <strong>textual message</strong> and <strong>state carrier</strong> describe functions of an object rather than additional object classes. An object acts as a textual message when it transfers governed work or evidence, and it acts as a state carrier when its content, transition evidence, or profile-defined location contributes to lifecycle reconstruction.</p><p>Every governance object contains or identifies:</p><ul><li>a stable object identifier;</li><li>a document type;</li><li>one creator identity;</li><li>one responsible role;</li><li>a stream identifier and sequence number;</li><li>a creation time;</li><li>a lifecycle profile and declared state;</li><li>typed references to related objects;</li><li>optional parent-work and thread identifiers;</li><li>optional completion, failure, recovery, or acceptance claims and their evidence references;</li><li>a risk level and human-approval requirement when required by the profile;</li><li>canonical textual content;</li><li>integrity evidence.</li></ul><p>A published governance object is immutable. Correction does not erase or rewrite the original object; it creates a new object that supersedes, rejects, qualifies, or resolves the earlier one. Multiple byte-identical source observations may refer to the same object without changing its meaning; the same identifier paired with different canonical content is a conflict, not an update.</p><p>The lifecycle state declared by an object is the state associated with that object under its profile at publication. The current authoritative state of governed work is reconstructed from the valid object set, accepted transitions, and profile rules. It is not obtained by mutating an earlier published object or by selecting the most recent timestamp.</p><p>Lifecycle state and business acceptance are orthogonal dimensions. A terminal state, archive location, or <code>done</code> declaration is state evidence only. It MUST NOT be reconstructed as business completion unless the applicable profile defines acceptance authority, required delivery evidence, and separation of duties, and the reader finds a valid acceptance object.</p><h2 id="_3-2-document-type-registries" tabindex="-1">3.2 Document-Type Registries <a class="header-anchor" href="#_3-2-document-type-registries" aria-label="Permalink to &quot;3.2 Document-Type Registries&quot;">​</a></h2><p>TMPA Core does not impose a universal business-document taxonomy. Each implementation profile instead publishes a finite document-type registry.</p><p>Each registry entry defines:</p><ul><li>the type name and version;</li><li>the governance responsibility represented by the type;</li><li>permitted creator roles;</li><li>required fields;</li><li>permitted reference relations;</li><li>the applicable lifecycle profile;</li><li>validation rules.</li></ul><p>Document types must not overlap ambiguously in authority. An execution report, for example, does not implicitly serve as its own independent review or approval. When a deployment permits an exception to separation of duties, the exception and its approving authority must be represented explicitly.</p><h2 id="_3-3-role-and-authority-model" tabindex="-1">3.3 Role and Authority Model <a class="header-anchor" href="#_3-3-role-and-authority-model" aria-label="Permalink to &quot;3.3 Role and Authority Model&quot;">​</a></h2><p>A TMPA role is a governance authority with a defined scope. It is not merely a prompt label or natural-language persona.</p><p>Each role definition identifies:</p><ul><li>a stable role identifier;</li><li>permitted object types;</li><li>permitted lifecycle actions;</li><li>separation-of-duty constraints;</li><li>the authority that assigns the role;</li><li>the assignment&#39;s validity period and revocation state.</li></ul><p>A profile MAY organize roles into execution, governance, and administration capability layers, but it must define permitted and prohibited directions and identify the identity or runtime control that enforces them. Declared capability boundaries and enforced capability boundaries MUST be reported separately.</p><p>An object’s <code>role</code> field declares the authority under which the creator acted; it does not create that authority. A reader validates the claim against an active role assignment and the applicable policy profile.</p><p>A participant may occupy more than one role only when the implementation profile explicitly permits the combination. A deployment claiming independent review must prohibit the same identity from acting as both executor and reviewer for the same governed result unless a recorded and authorized exception applies.</p><p>In an enterprise identity profile, the logical role is bound separately to a verifiable agent or workload identity, the human or organizational principal that remains accountable, the credential used for the action, the delegation source and scope, and the validity or revocation state. TMPA Core records and validates the governance claim; it does not issue credentials or enforce recursive permission attenuation.</p><h2 id="_3-4-lifecycle-model" tabindex="-1">3.4 Lifecycle Model <a class="header-anchor" href="#_3-4-lifecycle-model" aria-label="Permalink to &quot;3.4 Lifecycle Model&quot;">​</a></h2><p>A lifecycle profile consists of:</p><ul><li>a finite state set <code>S</code>;</li><li>an initial state <code>s0</code>;</li><li>a terminal-state set <code>F</code>;</li><li>an action set <code>A</code>;</li><li>a transition relation <code>T ⊆ S × A × S</code>;</li><li>an authorization function <code>Auth(role, action, object)</code>;</li><li>a validation function <code>Valid(object, transition)</code>.</li></ul><p>A transition is accepted only when:</p><ol><li>its source state matches the current authoritative state;</li><li>the transition is defined by <code>T</code>;</li><li>the initiating role is authorized;</li><li>required references and preconditions are satisfied;</li><li>the transition evidence passes schema and integrity validation.</li></ol><p>An illegal or unauthorized transition does not alter the authoritative lifecycle state. The attempt remains observable through a rejection, issue, alert, or equivalent profile-defined record rather than being silently discarded or repaired.</p><p>A lifecycle profile MUST additionally define: (1) which states require independent business acceptance; (2) which relations constitute reporting, review, acceptance, and archive authorization; (3) how parent and child work roll up; (4) which risk levels require human approval; and (5) failure types, recovery actions, and their persistent evidence. Lifecycle tools or physical locations may implement these rules but do not replace their semantic definitions.</p><h2 id="_3-5-textual-messages-single-writer-streams-and-asynchronous-parallelism" tabindex="-1">3.5 Textual Messages, Single-Writer Streams, and Asynchronous Parallelism <a class="header-anchor" href="#_3-5-textual-messages-single-writer-streams-and-asynchronous-parallelism" aria-label="Permalink to &quot;3.5 Textual Messages, Single-Writer Streams, and Asynchronous Parallelism&quot;">​</a></h2><p>TMPA&#39;s write plane combines a stable work carrier, single-writer objects, local seriality, and asynchronous composition.</p><p>For every governed task or work item <code>t</code>, a task-oriented profile defines one stable primary carrier <code>c_t</code>. The carrier establishes the identifier and minimum governing context of the work. Acceptance, execution reports, reviews, decisions, corrections, and recovery records are separate objects that reference <code>c_t</code>; they do not become additional mutable copies of the task. “One task, one carrier” therefore means one stable primary reference point, not one document that every participant edits.</p>`,54))])}const b=a(c,[["render",d]]);export{f as __pageData,b as default};
